async function updatePdfPageCount(file, inputId, statusId) { try { const source=await loadPdfDocument(file); document.getElementById(inputId).placeholder=`1-${source.getPageCount()}`; setStatus(statusId,`${file.name} · ${source.getPageCount()} pages ready.`); return source; } catch (error) { setStatus(statusId,error.message,'error'); return null; } }
function renderRotatePdf(tool) {
  const content=pdfToolContent('Rotate PDF pages','Rotate every page or selected pages without changing the rest of the document.','rotate','<div class="settings-grid"><div class="field"><label for="rotate-pages">Pages</label><input id="rotate-pages" value="all" placeholder="all or 1-3,5" /></div><div class="field"><label for="rotate-degrees">Rotation</label><select id="rotate-degrees"><option value="90">90° clockwise</option><option value="180">180°</option><option value="270">270° clockwise</option></select></div></div><div class="tool-actions"><button class="button" id="rotate-run" disabled>Rotate PDF</button><button class="button button-secondary" id="rotate-reset">Reset</button></div>');app.innerHTML=toolShell(tool,content,'<div class="notice"><strong>Preserves content.</strong> Pages are copied into a new PDF with the selected rotation applied.</div>');let file=null;bindPdfSingleFile('rotate',(event,selected)=>{if(event==='selected'){file=selected;updatePdfPageCount(file,'rotate-pages','rotate-status');}});document.getElementById('rotate-run').addEventListener('click',async()=>{try{const source=await loadPdfDocument(file);const pages=source.getPages();const selected=document.getElementById('rotate-pages').value.trim().toLowerCase()==='all'?pages.map((_,index)=>index):pdfPageNumbers(document.getElementById('rotate-pages').value, pages.length);if(!selected.length)throw new Error('Enter valid page numbers or use all.');const amount=Number(document.getElementById('rotate-degrees').value);selected.forEach(index=>pages[index].setRotation(PDFLib.degrees((pages[index].getRotation().angle+amount)%360)));pdfDownload(await source.save(),pdfFileName(file.name,'rotated'));setProgress('rotate-progress',100);setStatus('rotate-status','Rotated PDF downloaded.','success');}catch(error){setStatus('rotate-status',error.message,'error');}});document.getElementById('rotate-reset').addEventListener('click',()=>navigate('#/tool/rotate-pdf'));
}
function renderDeletePdfPages(tool) {
  const content=pdfToolContent('Delete PDF pages','Remove selected page numbers and download the remaining document.','deletepdf','<div class="field"><label for="deletepdf-pages">Pages to delete</label><input id="deletepdf-pages" value="2" placeholder="2,4-6" /></div><div class="tool-actions"><button class="button" id="deletepdf-run" disabled>Delete pages</button><button class="button button-secondary" id="deletepdf-reset">Reset</button></div>');app.innerHTML=toolShell(tool,content,'<div class="notice"><strong>Safety check.</strong> The last remaining page cannot be deleted.</div>');let file=null;bindPdfSingleFile('deletepdf',(event,selected)=>{if(event==='selected'){file=selected;updatePdfPageCount(file,'deletepdf-pages','deletepdf-status');}});document.getElementById('deletepdf-run').addEventListener('click',async()=>{try{const source=await loadPdfDocument(file);const remove=new Set(pdfPageNumbers(document.getElementById('deletepdf-pages').value,source.getPageCount()));if(!remove.size)throw new Error('Enter valid page numbers to delete.');if(remove.size>=source.getPageCount())throw new Error('At least one page must remain.');for(const index of [...remove].sort((a,b)=>b-a))source.removePage(index);pdfDownload(await source.save(),pdfFileName(file.name,'pages-deleted'));setProgress('deletepdf-progress',100);setStatus('deletepdf-status',`${remove.size} page${remove.size===1?'':'s'} deleted.`,'success');}catch(error){setStatus('deletepdf-status',error.message,'error');}});document.getElementById('deletepdf-reset').addEventListener('click',()=>navigate('#/tool/delete-pdf-pages'));
}
function renderWatermark(tool) {
  const content=pdfToolContent('Add a PDF watermark','Stamp a visible text watermark on selected pages.','watermark','<div class="settings-grid"><div class="field"><label for="watermark-text">Watermark text</label><input id="watermark-text" value="CONFIDENTIAL" /></div><div class="field"><label for="watermark-opacity">Opacity</label><input id="watermark-opacity" type="range" min="0.1" max="1" step="0.1" value="0.25" /></div><div class="field"><label for="watermark-pages">Pages</label><input id="watermark-pages" value="all" placeholder="all or 1-3,5" /></div><div class="field"><label for="watermark-size">Font size</label><input id="watermark-size" type="number" min="8" max="120" value="42" /></div></div><div class="tool-actions"><button class="button" id="watermark-run" disabled>Add watermark</button><button class="button button-secondary" id="watermark-reset">Reset</button></div>');app.innerHTML=toolShell(tool,content,'<div class="notice"><strong>Visible stamp.</strong> Watermarks are rendered into page content and are not a security feature.</div>');let file=null;bindPdfSingleFile('watermark',(event,selected)=>{if(event==='selected'){file=selected;updatePdfPageCount(file,'watermark-pages','watermark-status');}});document.getElementById('watermark-run').addEventListener('click',async()=>{try{const source=await loadPdfDocument(file);const font=await source.embedFont(PDFLib.StandardFonts.HelveticaBold);const pages=source.getPages();const selected=document.getElementById('watermark-pages').value.trim().toLowerCase()==='all'?pages.map((_,index)=>index):pdfPageNumbers(document.getElementById('watermark-pages').value,pages.length);if(!selected.length)throw new Error('Enter valid page numbers or use all.');const text=document.getElementById('watermark-text').value.trim();if(!text)throw new Error('Enter watermark text.');const size=Math.max(8,Number(document.getElementById('watermark-size').value)||42);const opacity=Number(document.getElementById('watermark-opacity').value)||.25;selected.forEach(index=>{const page=pages[index];const {width,height}=page.getSize();page.drawText(text,{x:width*.16,y:height*.48,size,font,color:PDFLib.rgb(.18,.27,.65),opacity,rotate:PDFLib.degrees(35)});});pdfDownload(await source.save(),pdfFileName(file.name,'watermarked'));setProgress('watermark-progress',100);setStatus('watermark-status','Watermarked PDF downloaded.','success');}catch(error){setStatus('watermark-status',error.message,'error');}});document.getElementById('watermark-reset').addEventListener('click',()=>navigate('#/tool/add-watermark'));
}
function renderSignPdf(tool) {
  const content=pdfToolContent('Add a visible signature','Type a signature, choose the pages, and place it near the bottom-right corner. This is a visual mark, not a certificate-based digital signature.','sign','<div class="settings-grid"><div class="field"><label for="sign-text">Signature text</label><input id="sign-text" placeholder="Your name" /></div><div class="field"><label for="sign-pages">Pages</label><input id="sign-pages" value="1" placeholder="all or 1-3,5" /></div><div class="field"><label for="sign-size">Font size</label><input id="sign-size" type="number" min="8" max="72" value="24" /></div><div class="field"><label for="sign-label">Label</label><input id="sign-label" value="Signed" /></div></div><div class="tool-actions"><button class="button" id="sign-run" disabled>Sign PDF</button><button class="button button-secondary" id="sign-reset">Reset</button></div>');app.innerHTML=toolShell(tool,content,'<div class="notice"><strong>Important.</strong> This creates a visible signature. It does not provide legal identity verification, encryption, or certificate validation.</div>');let file=null;bindPdfSingleFile('sign',(event,selected)=>{if(event==='selected'){file=selected;updatePdfPageCount(file,'sign-pages','sign-status');}});document.getElementById('sign-run').addEventListener('click',async()=>{try{const source=await loadPdfDocument(file);const font=await source.embedFont(PDFLib.StandardFonts.HelveticaOblique);const pages=source.getPages();const selected=document.getElementById('sign-pages').value.trim().toLowerCase()==='all'?pages.map((_,index)=>index):pdfPageNumbers(document.getElementById('sign-pages').value,pages.length);const text=document.getElementById('sign-text').value.trim();if(!selected.length)throw new Error('Enter valid page numbers.');if(!text)throw new Error('Enter a signature.');const size=Math.max(8,Number(document.getElementById('sign-size').value)||24);const label=document.getElementById('sign-label').value.trim();selected.forEach(index=>{const page=pages[index];const {width}=page.getSize();page.drawText(label,{x:width-160,y:48,size:10,font,color:PDFLib.rgb(.35,.4,.55)});page.drawText(text,{x:width-160,y:28,size,font,color:PDFLib.rgb(.08,.15,.42)});});pdfDownload(await source.save(),pdfFileName(file.name,'signed'));setProgress('sign-progress',100);setStatus('sign-status','Signed PDF downloaded.','success');}catch(error){setStatus('sign-status',error.message,'error');}});document.getElementById('sign-reset').addEventListener('click',()=>navigate('#/tool/sign-pdf'));
}
function renderWordCounter(tool){
  const content=`<h2>See the shape of your writing</h2><p>Paste or type text to get live counts and a quick reading-time estimate.</p><textarea class="text-tool" id="counter-text" placeholder="Start typing or paste text here..."></textarea><div class="settings-grid"><div class="info-panel"><strong id="counter-words">0</strong><small>Words</small></div><div class="info-panel"><strong id="counter-characters">0</strong><small>Characters</small></div><div class="info-panel"><strong id="counter-sentences">0</strong><small>Sentences</small></div><div class="info-panel"><strong id="counter-reading">0 min</strong><small>Reading time</small></div></div><div class="status" id="counter-status"></div>`; app.innerHTML=toolShell(tool,content,'<div class="notice"><strong>Local only.</strong> Text is calculated in the page and is never sent to a server.</div>'); const input=document.getElementById('counter-text'); input.addEventListener('input',()=>{const text=input.value;const words=text.trim()?text.trim().split(/\s+/).length:0;const sentences=text.match(/[.!?]+(?=\s|$)/g)?.length||0;document.getElementById('counter-words').textContent=words;document.getElementById('counter-characters').textContent=text.length;document.getElementById('counter-sentences').textContent=sentences;document.getElementById('counter-reading').textContent=`${words?Math.max(1,Math.ceil(words/200)):0} min`;});
}
function textToolShell(tool,title,description,placeholder){const content=`<h2>${title}</h2><p>${description}</p><textarea class="text-tool" id="text-tool-input" placeholder="${placeholder}"></textarea><div class="tool-actions"><button class="button" id="text-tool-run">Process text</button><button class="button button-secondary" id="text-tool-copy">Copy result</button><button class="button button-secondary" id="text-tool-reset">Reset</button></div><div class="result-box" id="text-tool-result">Your result will appear here.</div><div class="status" id="text-tool-status"></div>`; app.innerHTML=toolShell(tool,content); return {input:document.getElementById('text-tool-input'),result:document.getElementById('text-tool-result')};}
function bindTextTool(tool,process){const {input,result}=textToolShell(tool,'A small text transformer','Run a focused transformation locally, then copy the result.','Paste text here…');document.getElementById('text-tool-run').addEventListener('click',()=>{result.textContent=process(input.value);setStatus('text-tool-status','Result updated.','success');});document.getElementById('text-tool-copy').addEventListener('click',async()=>{await navigator.clipboard?.writeText(result.textContent);setStatus('text-tool-status','Result copied.','success');});document.getElementById('text-tool-reset').addEventListener('click',()=>navigate(`#/tool/${tool.id}`));}
function renderCaseConverter(tool){bindTextTool(tool,text=>{const mode=prompt('Choose: lower, upper, title, or sentence','title')||'title';if(mode==='lower')return text.toLowerCase();if(mode==='upper')return text.toUpperCase();if(mode==='sentence')return text.toLowerCase().replace(/(^|[.!?]\s+)([a-z])/g,(_,a,b)=>a+b.toUpperCase());return text.toLowerCase().replace(/\b\w/g,char=>char.toUpperCase());});}
function renderDuplicateLines(tool){bindTextTool(tool,text=>[...new Set(text.split(/\r?\n/))].join('\n'));}
function renderBase64(tool){const {input,result}=textToolShell(tool,'Encode or decode Base64','Use UTF-8-safe browser APIs for text payloads.','Paste text or Base64 here…');const mode=document.createElement('div');mode.innerHTML='<select id="base64-mode"><option value="encode">Encode to Base64</option><option value="decode">Decode Base64</option></select>';document.getElementById('text-tool-run').before(mode.firstChild);document.getElementById('text-tool-run').addEventListener('click',()=>{try{const value=input.value;result.textContent=document.getElementById('base64-mode').value==='encode'?btoa(unescape(encodeURIComponent(value))):decodeURIComponent(escape(atob(value)));setStatus('text-tool-status','Result updated.','success');}catch(e){result.textContent='';setStatus('text-tool-status','That is not valid Base64 text.','error');}});document.getElementById('text-tool-copy').addEventListener('click',async()=>{await navigator.clipboard?.writeText(result.textContent);setStatus('text-tool-status','Result copied.','success');});document.getElementById('text-tool-reset').addEventListener('click',()=>navigate('#/tool/base64'));}
function renderJsonFormatter(tool){const content=`<h2>Readable JSON, reliable feedback</h2><p>Validate and format JSON or produce a compact minified version.</p><textarea class="text-tool" id="json-input" placeholder='{"hello":"Toolora"}'></textarea><div class="tool-actions"><button class="button" id="json-format">Format JSON</button><button class="button button-secondary" id="json-minify">Minify JSON</button><button class="button button-secondary" id="json-copy">Copy result</button></div><div class="result-box" id="json-result">Your formatted JSON will appear here.</div><div class="status" id="json-status"></div>`;app.innerHTML=toolShell(tool,content);const input=document.getElementById('json-input'),result=document.getElementById('json-result');const run=minify=>{try{const parsed=JSON.parse(input.value);result.textContent=JSON.stringify(parsed,null,minify?0:2);setStatus('json-status','Valid JSON.','success');}catch(error){setStatus('json-status',`Invalid JSON: ${error.message}`,'error');}};document.getElementById('json-format').addEventListener('click',()=>run(false));document.getElementById('json-minify').addEventListener('click',()=>run(true));document.getElementById('json-copy').addEventListener('click',async()=>{await navigator.clipboard?.writeText(result.textContent);setStatus('json-status','Result copied.','success');});}
function renderUrlEncoder(tool){const {input,result}=textToolShell(tool,'Encode or decode URLs','Transform URL components without changing the page location.','https://example.com/hello world');const mode=document.createElement('select');mode.id='url-mode';mode.innerHTML='<option value="encode">Encode</option><option value="decode">Decode</option>';document.getElementById('text-tool-run').before(mode);document.getElementById('text-tool-run').addEventListener('click',()=>{try{result.textContent=document.getElementById('url-mode').value==='encode'?encodeURIComponent(input.value):decodeURIComponent(input.value);setStatus('text-tool-status','Result updated.','success');}catch(e){setStatus('text-tool-status','Could not decode that URL component.','error');}});document.getElementById('text-tool-copy').addEventListener('click',async()=>{await navigator.clipboard?.writeText(result.textContent);setStatus('text-tool-status','Result copied.','success');});document.getElementById('text-tool-reset').addEventListener('click',()=>navigate('#/tool/url-encoder'));}
function renderColorConverter(tool){const content=`<h2>One color, three useful formats</h2><p>Enter a HEX color to see RGB and HSL values with a visual swatch.</p><div class="settings-grid"><div class="field"><label for="hex-color">HEX</label><input id="hex-color" value="#1f45ff" placeholder="#1f45ff" /></div><div class="field"><label for="native-color">Pick a color</label><input id="native-color" type="color" value="#1f45ff" /></div></div><div class="preview-box" id="color-preview" style="background:#1f45ff;min-height:100px"></div><ul class="info-list" id="color-values"></ul><div class="status" id="color-status"></div>`;app.innerHTML=toolShell(tool,content);const hex=document.getElementById('hex-color'),native=document.getElementById('native-color');function update(value){let clean=value.trim().replace('#','');if(/^[0-9a-fA-F]{3}$/.test(clean))clean=clean.split('').map(x=>x+x).join('');if(!/^[0-9a-fA-F]{6}$/.test(clean)){setStatus('color-status','Enter a valid six-digit HEX color.','error');return;}const r=parseInt(clean.slice(0,2),16),g=parseInt(clean.slice(2,4),16),b=parseInt(clean.slice(4,6),16);const rn=r/255,gn=g/255,bn=b/255,max=Math.max(rn,gn,bn),min=Math.min(rn,gn,bn),d=max-min;let h=0,s=0,l=(max+min)/2;if(d){s=d/(1-Math.abs(2*l-1));h=max===rn?60*((gn-bn)/d%6):max===gn?60*((bn-rn)/d+2):60*((rn-gn)/d+4);if(h<0)h+=360;}h=Math.round(h);s=Math.round(s*100);l=Math.round(l*100);const valueHex=`#${clean.toLowerCase()}`;native.value=valueHex;document.getElementById('color-preview').style.background=valueHex;document.getElementById('color-values').innerHTML=`<li><span>HEX</span><span>${valueHex}</span></li><li><span>RGB</span><span>rgb(${r}, ${g}, ${b})</span></li><li><span>HSL</span><span>hsl(${h}, ${s}%, ${l}%)</span></li>`;setStatus('color-status','Color converted.','success');}hex.addEventListener('input',()=>update(hex.value));native.addEventListener('input',()=>{hex.value=native.value;update(native.value);});update(hex.value);}
function renderUuidGenerator(tool){const content=`<h2>Generate UUID v4 identifiers</h2><p>Create random IDs with the browser's cryptographic random number generator.</p><div class="result-box" id="uuid-result" style="font-size:18px;min-height:80px;display:grid;place-items:center">Click generate</div><div class="tool-actions"><button class="button" id="uuid-generate">Generate UUID</button><button class="button button-secondary" id="uuid-copy">Copy</button></div><div class="status" id="uuid-status"></div>`;app.innerHTML=toolShell(tool,content);const result=document.getElementById('uuid-result');function generate(){const uuid=crypto.randomUUID?crypto.randomUUID():[1e7]+-1e3+-4e3+-8e3+-1e11;result.textContent=uuid;}document.getElementById('uuid-generate').addEventListener('click',generate);document.getElementById('uuid-copy').addEventListener('click',async()=>{await navigator.clipboard?.writeText(result.textContent);setStatus('uuid-status','UUID copied.','success');});generate();}
function renderPercentage(tool){const content=`<h2>Quick percentage answers</h2><p>Choose the question you are trying to solve.</p><div class="field"><label for="percentage-mode">Calculation</label><select id="percentage-mode"><option value="of">What is X% of Y?</option><option value="change">Percentage change from A to B</option><option value="is">X is what percent of Y?</option></select></div><div class="settings-grid"><div class="field"><label for="percentage-a" id="percentage-a-label">X</label><input id="percentage-a" type="number" value="15" /></div><div class="field"><label for="percentage-b" id="percentage-b-label">Y</label><input id="percentage-b" type="number" value="200" /></div></div><div class="result-box" id="percentage-result">45</div><div class="tool-actions"><button class="button" id="percentage-calculate">Calculate</button></div>`;app.innerHTML=toolShell(tool,content);const mode=document.getElementById('percentage-mode'),a=document.getElementById('percentage-a'),b=document.getElementById('percentage-b'),result=document.getElementById('percentage-result');function calc(){const x=Number(a.value),y=Number(b.value);if(mode.value==='of')result.textContent=`${x}% of ${y} = ${(x/100*y).toLocaleString()}`;else if(mode.value==='is')result.textContent=`${x} is ${(x/y*100).toFixed(2)}% of ${y}`;else result.textContent=`Change from ${x} to ${y} = ${((y-x)/x*100).toFixed(2)}%`;}mode.addEventListener('change',()=>{document.getElementById('percentage-a-label').textContent=mode.value==='change'?'From':'X';document.getElementById('percentage-b-label').textContent=mode.value==='change'?'To':'Y';});document.getElementById('percentage-calculate').addEventListener('click',calc);calc();}
function renderAspectRatio(tool){const content=`<h2>Keep proportions intact</h2><p>Enter any three values to calculate the missing dimension.</p><div class="settings-grid"><div class="field"><label for="ratio-width">Width</label><input id="ratio-width" type="number" value="1920" /></div><div class="field"><label for="ratio-height">Height</label><input id="ratio-height" type="number" value="1080" /></div><div class="field"><label for="ratio-target-width">Target width</label><input id="ratio-target-width" type="number" placeholder="Optional" /></div><div class="field"><label for="ratio-target-height">Target height</label><input id="ratio-target-height" type="number" placeholder="Optional" /></div></div><div class="result-box" id="ratio-result">Aspect ratio: 16:9</div><div class="tool-actions"><button class="button" id="ratio-calculate">Calculate</button></div>`;app.innerHTML=toolShell(tool,content);const result=document.getElementById('ratio-result');document.getElementById('ratio-calculate').addEventListener('click',()=>{const w=Number(document.getElementById('ratio-width').value),h=Number(document.getElementById('ratio-height').value),tw=Number(document.getElementById('ratio-target-width').value),th=Number(document.getElementById('ratio-target-height').value);const gcd=(x,y)=>y?gcd(y,x%y):x;const divisor=gcd(w,h);let output=`Aspect ratio: ${w/divisor}:${h/divisor}`;if(tw&&!th)output+=`\nTarget height: ${(tw*h/w).toFixed(2)} px`;if(th&&!tw)output+=`\nTarget width: ${(th*w/h).toFixed(2)} px`;result.textContent=output;});}
function renderGenericUtility(tool){const content=`<h2>${escapeHtml(tool.title)}</h2><p>This utility is available in the directory and its processing surface is ready for the next focused implementation module.</p><div class="notice"><strong>Choose another tool.</strong> The currently implemented release includes image processing, text utilities, JSON, URL, color, UUID, and calculator tools.</div><a class="button" href="#/tools">Back to all tools ↗</a>`;app.innerHTML=toolShell(tool,content);}

function renderStaticPage(type){const pages={about:{eyebrow:'THE IDEA',title:'Tools that respect your time',text:'Toolora is a small, focused toolbox for the moments when a full application would be overkill.',body:`<h2>Designed for the in-between moments</h2><p>Rename a file. Shrink an image. Validate a JSON payload. These tasks should not require a signup flow, a tutorial, or a data pipeline. Toolora brings the useful parts into a calm interface that works directly in your browser whenever the platform allows it.</p><h2>What we believe</h2><ul><li>Simple tools should be simple to use.</li><li>Privacy should be the default, not a premium feature.</li><li>Unavailable functionality should be labeled honestly.</li></ul>`},contact:{eyebrow:'SAY HELLO',title:'Contact Toolora',text:'Found a bug, have a request, or just want to say hello?',body:`<h2>Send a note</h2><form id="contact-form"><div class="settings-grid"><div class="field"><label for="contact-name">Name</label><input id="contact-name" required /></div><div class="field"><label for="contact-email">Email</label><input id="contact-email" type="email" required /></div></div><div class="field"><label for="contact-message">Message</label><textarea id="contact-message" class="text-tool" style="min-height:170px" required></textarea></div><button class="button" type="submit">Prepare email</button><div class="status" id="contact-status"></div></form>`},privacy:{eyebrow:'YOUR FILES, YOUR CONTROL',title:'Privacy policy',text:'A clear explanation of what happens when you use Toolora.',body:`<h2>Browser-native processing</h2><p>Image and text tools in this release use browser APIs such as Canvas, FileReader, and Web Crypto. Your inputs remain on your device unless you choose an external service that is clearly identified in the interface.</p><h2>Local preferences</h2><p>Toolora stores theme preference, recently used tools, and newsletter status in local browser storage. No account is required for these features.</p><h2>Future server tools</h2><p>PDF and complex document conversion may require a server processing module in a later release. When that happens, the upload destination, retention period, and limits will be disclosed before processing.</p>`},terms:{eyebrow:'PLAIN LANGUAGE',title:'Terms of service',text:'Use the toolbox responsibly and keep your own backups for important files.',body:`<h2>Use at your own discretion</h2><p>Toolora is provided as a convenience. Verify important output before publishing, submitting, or deleting your originals. Do not use the service to process unlawful or harmful material.</p><h2>Availability</h2><p>Browser capabilities vary by device and browser version. Features marked unavailable are not offered and do not accept uploads.</p>`}};const page=pages[type]||pages.about;app.innerHTML=`${pageHeading(page.eyebrow,page.title,page.text)}<section class="page content-card" style="max-width:900px">${page.body}</section>`;if(type==='contact')document.getElementById('contact-form').addEventListener('submit',e=>{e.preventDefault();const name=document.getElementById('contact-name').value,email=document.getElementById('contact-email').value,message=document.getElementById('contact-message').value;window.location.href=`mailto:hello@toolora.local?subject=Toolora message from ${encodeURIComponent(name)}&body=${encodeURIComponent(`${message}\n\nReply to: ${email}`)}`;setStatus('contact-status','Opening your email app…','success');});}
function renderNotFound(){app.innerHTML=`<section class="page not-found"><div class="eyebrow" style="justify-content:center">WRONG TURN</div><h1>404</h1><p class="hero-subtitle" style="margin:15px auto 24px">That page does not exist, but there is probably a useful tool nearby.</p><a class="button" href="#/tools">Explore all tools ↗</a></section>`;}
function renderProfile(){
  const profile=getProfile();
  const accents=[['blue','Ocean blue','#2453d4'],['violet','Violet','#7c3aed'],['emerald','Emerald','#0f9f73'],['rose','Rose','#d14b72'],['amber','Amber','#c77b16'],['slate','Slate','#53657d']];
  app.innerHTML=`${pageHeading('PROFILE','Your profile','Personalize how Toolora looks and how your profile appears in this browser.')}<section class="page profile-shell"><form class="profile-editor" id="profile-form"><div class="profile-card profile-identity"><div class="profile-identity-heading"><div class="profile-avatar-large" id="profile-avatar-preview">${profileAvatarMarkup(profile,'profile-avatar')}</div><div><div class="eyebrow">LOCAL PROFILE</div><h2>${escapeHtml(profile.name)}</h2><p>Saved only on this device. Authentication is not connected.</p></div></div><div class="profile-photo-actions"><label class="button button-small" for="profile-avatar-input">Upload / change image</label><input class="sr-only" id="profile-avatar-input" type="file" accept="image/png,image/jpeg,image/webp" /><button class="button button-small button-secondary" id="profile-avatar-remove" type="button">Remove image</button></div><div class="field"><label for="profile-name">Display name</label><input id="profile-name" maxlength="60" value="${escapeHtml(profile.name)}" placeholder="Your name" required /></div></div><div class="profile-card"><div class="section-header compact"><div><div class="eyebrow">APPEARANCE</div><h2>Make it yours</h2><p>Choose an accent color and display mode for the whole workspace.</p></div></div><div class="field"><label>Accent color</label><div class="accent-grid" role="radiogroup" aria-label="Accent color">${accents.map(([id,label,color])=>`<label class="accent-option ${profile.accent===id?'selected':''}"><input type="radio" name="profile-accent" value="${id}" ${profile.accent===id?'checked':''} /><span class="accent-swatch" style="--accent:${color}"></span><span>${label}</span></label>`).join('')}</div></div><div class="field profile-mode-field"><label>Display mode</label><div class="mode-options">${[['light','Light'],['dark','Dark'],['system','System']].map(([id,label])=>`<label class="mode-option"><input type="radio" name="profile-mode" value="${id}" ${profile.mode===id?'checked':''} /><span>${label}</span></label>`).join('')}</div></div><div class="tool-actions"><button class="button" type="submit">Save profile</button><a class="button button-secondary" href="#/tools">Cancel</a></div><div class="status" id="profile-status" aria-live="polite"></div></div></form><aside class="profile-summary"><div class="profile-card"><div class="eyebrow">PROFILE PREVIEW</div><div class="profile-preview" id="profile-preview">${profileAvatarMarkup(profile,'profile-avatar-medium')}<div><strong>${escapeHtml(profile.name)}</strong><small>Toolora member</small></div></div><div class="notice"><strong>Private by default.</strong> Your profile name, image, and appearance preferences stay in local browser storage until you connect a real account system.</div></div><div class="profile-card profile-links"><h3>Account spaces</h3><a href="#/dashboard">Dashboard <span>↗</span></a><a href="#/account/settings">Account settings <span>↗</span></a><a href="#/login">Sign-in boundary <span>↗</span></a></div></aside></section>`;
  let avatar=profile.avatar;
  const nameInput=document.getElementById('profile-name'); const preview=document.getElementById('profile-avatar-preview'); const profilePreview=document.getElementById('profile-preview');
  function updatePreview(){const next={...profile,name:nameInput.value.trim()||profileDefaults.name,avatar};preview.innerHTML=profileAvatarMarkup(next,'profile-avatar');profilePreview.innerHTML=`${profileAvatarMarkup(next,'profile-avatar-medium')}<div><strong>${escapeHtml(next.name)}</strong><small>Toolora member</small></div>`;}
  document.getElementById('profile-avatar-input').addEventListener('change',event=>{const file=event.target.files?.[0];if(!file)return;if(file.size>2*1024*1024){setStatus('profile-status','Please choose an image smaller than 2 MB.','error');event.target.value='';return;}const reader=new FileReader();reader.onload=()=>{avatar=reader.result;updatePreview();setStatus('profile-status','Image ready. Save your profile to keep it.');};reader.readAsDataURL(file);});
  document.getElementById('profile-avatar-remove').addEventListener('click',()=>{avatar='';document.getElementById('profile-avatar-input').value='';updatePreview();setStatus('profile-status','Image removed. Save your profile to confirm.');});
  nameInput.addEventListener('input',updatePreview);
  document.querySelectorAll('input[name="profile-accent"]').forEach(input=>input.addEventListener('change',()=>document.body.dataset.accent=input.value));
  document.querySelectorAll('input[name="profile-mode"]').forEach(input=>input.addEventListener('change',()=>{const mode=input.value;if(mode==='dark')document.body.classList.add('dark');else if(mode==='light')document.body.classList.remove('dark');else document.body.classList.toggle('dark',Boolean(window.matchMedia?.('(prefers-color-scheme: dark)').matches));document.getElementById('theme-toggle').textContent=document.body.classList.contains('dark')?'☀':'☾';}));
  document.getElementById('profile-form').addEventListener('submit',event=>{event.preventDefault();const next={name:nameInput.value.trim()||profileDefaults.name,avatar,accent:document.querySelector('input[name="profile-accent"]:checked').value,mode:document.querySelector('input[name="profile-mode"]:checked').value};saveProfile(next);applyProfileAppearance();updateProfileHeader();setStatus('profile-status','Profile saved on this device.','success');updatePreview();});
}
function renderAccountSurface(type){if(type==='profile')return renderProfile();const labels={login:['Sign in to Toolora','Authentication is not connected in this browser-only release.'],register:['Create your Toolora account','Account creation will be available when a secure server-side auth provider is configured.'],dashboard:['Your dashboard','A focused dashboard will appear after secure authentication is enabled.'],'account-settings':['Account settings','Preferences are currently stored locally in this browser.']};const [title,text]=labels[type]||labels.login;app.innerHTML=`${pageHeading('ACCOUNT',title,text)}<section class="page account-layout"><div class="account-card"><div class="account-icon">◎</div><h2>${title}</h2><p>${text}</p><div class="notice"><strong>Nothing is being simulated.</strong> Toolora currently runs as a static browser-first app, so it does not collect passwords, create fake sessions, or display fake account data.</div><div class="tool-actions"><a class="button" href="#/profile">Open profile</a><a class="button button-secondary" href="#/tools">Continue without an account</a></div></div><aside class="info-panel"><h3>What is available now</h3><ul class="info-list"><li><span>Profile</span><span>Saved locally</span></li><li><span>Theme</span><span>Saved locally</span></li><li><span>Favorites</span><span>Saved locally</span></li><li><span>File processing</span><span>Local where supported</span></li></ul></aside></section>`;}
function route(){const {path}=getRoute();if(path==='/'||path==='')renderHome();else if(path==='/tools')renderDirectory();else if(path==='/calculators'&&window.TooloraCalculatorUI)window.TooloraCalculatorUI.renderCalculatorsDirectory();else if(path.startsWith('/calculator/')&&window.TooloraCalculatorUI){const calculator=window.TooloraCalculatorUI.calculatorById(path.split('/')[2]);calculator?window.TooloraCalculatorUI.renderCalculator(calculator):renderNotFound();}else if(path.startsWith('/tool/'))renderTool(path.split('/')[2]);else if(['/about','/contact','/privacy','/terms'].includes(path))renderStaticPage(path.slice(1));else if(['/login','/register','/profile','/dashboard','/account/settings'].includes(path))renderAccountSurface(path.slice(1).replace('/','-'));else renderNotFound();window.scrollTo({top:0,behavior:'smooth'});}

document.getElementById('theme-toggle').addEventListener('click',()=>{const isDark=!document.body.classList.contains('dark');document.body.classList.toggle('dark',isDark);localStorage.setItem('toolora-theme',isDark?'dark':'light');const profile=getProfile();if(localStorage.getItem('toolora-profile')){profile.mode=isDark?'dark':'light';saveProfile(profile);}document.getElementById('theme-toggle').textContent=isDark?'☀':'☾';});
applyProfileAppearance();
updateProfileHeader();
document.getElementById('mobile-menu-toggle').addEventListener('click',()=>{const nav=document.getElementById('mobile-nav');nav.hidden=!nav.hidden;});
document.getElementById('newsletter-form').addEventListener('submit',e=>{e.preventDefault();localStorage.setItem('toolora-newsletter',document.getElementById('newsletter-email').value);document.getElementById('newsletter-status').textContent='You are on the list — thank you.';e.target.reset();});
window.addEventListener('hashchange',()=>{document.getElementById('mobile-nav').hidden=true;route();});
route();
